// Profile store: materialized view + journal (the journal is the ONLY
// authority; profile.json is a pure projection - r2 §14 verify/rebuild).
// Every LLM-proposed op passes deterministic guards here (LLM nominates,
// code decides - §3.3).

import path from 'node:path';
import { randomUUID } from 'node:crypto';
import fs from 'node:fs';
import type { PathGuard } from '../core/path-guard.js';
import { loadJson, saveJson, readText, writeText } from '../vault/vault.js';
import type { Policy } from '../config/schema.js';
import {
  CONFIDENCE_CAP,
  emptyProfile,
  JOURNAL_VERSION,
  PARTITIONS,
  type ApplyReport,
  type Evidence,
  type EvidenceKind,
  type InboxItem,
  type JournalRecord,
  type Partition,
  type ProfileDoc,
  type ProfileEntry,
  type ProfileOp,
} from './types.js';
import { checkAddAgainstSchema, type ProfileSchema } from './schema.js';
import { tryParseJournalRecord } from './shapes.js';
import { matchFilesRecursive } from '../core/fs-walk.js';

const DAY_MS = 86_400_000;

export function profileFilePath(dataDir: string): string {
  return path.join(dataDir, 'profile.json');
}

export function journalFilePath(dataDir: string): string {
  return path.join(dataDir, 'profile_journal.jsonl');
}

// ── snapshot basepoint (v1.8.0, design doc §14 ③) ─────────────────────────
// The journal grows forever; the snapshot folds its history into one DPAPI
// document and moves the folded records into a timestamped archive shard.
// Replay order: snapshot → archives (name order) → live journal, skipping
// records at or before the snapshot baseline — so verify/rebuild stay correct
// without knowing whether a snapshot exists.

export const SNAPSHOT_FILE = 'profile_snapshot.json';
export const ARCHIVE_PREFIX = 'profile_journal.archive-';

export interface ProfileSnapshot {
  version: 1;
  /** ts of the LAST journal record folded into `doc`. */
  baselineTs: string;
  recordsFolded: number;
  doc: ProfileDoc;
}

export function snapshotFilePath(dataDir: string): string {
  return path.join(dataDir, SNAPSHOT_FILE);
}

function loadSnapshot(guard: PathGuard, dataDir: string): ProfileSnapshot | null {
  const snap = loadJson<ProfileSnapshot>(guard, snapshotFilePath(dataDir));
  if (!snap || snap.version !== 1 || typeof snap.baselineTs !== 'string' || !snap.doc?.partitions) return null;
  return snap;
}

function listArchiveFiles(guard: PathGuard, dataDir: string): string[] {
  try {
    return fs.readdirSync(guard.assert(dataDir))
      .filter((f) => f.startsWith(ARCHIVE_PREFIX) && f.endsWith('.jsonl'))
      .sort(); // timestamped names sort chronologically
  } catch {
    return [];
  }
}

/** Replay one JSONL text into `doc`, skipping records at/before the baseline. */
function replayText(
  doc: ProfileDoc,
  text: string,
  baselineTs: string,
  stats: { records: number; truncatedTail: number; badRecords: number; isLive: boolean },
): void {
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i]!.trim();
    if (!trimmed) continue;
    // A torn tail only counts on the LIVE journal — archives are closed files.
    const tornTail = (): boolean => {
      const isLast = lines.slice(i + 1).every((l) => !l.trim());
      if (stats.isLive && isLast) {
        stats.truncatedTail = lines.length - i;
        return true;
      }
      return false;
    };
    let rec: JournalRecord | null = null;
    try {
      rec = tryParseJournalRecord(JSON.parse(trimmed));
    } catch {
      rec = null;
    }
    if (!rec) {
      if (tornTail()) break;
      // mid-file unreadable record: count it and keep going (the journal is
      // append-only/immutable, so a bad line is never rewritten).
      stats.badRecords += 1;
      continue;
    }
    // Baseline skip: only records CARRYING a ts can be proven folded. A
    // ts-less record is always applied (applyOpPermissive tolerates it).
    if (baselineTs && rec.ts && String(rec.ts) <= baselineTs) continue;
    try {
      if (rec.v === JOURNAL_VERSION && rec.entries) {
        // v2 (③A): the record carries each touched entry's FULL final state,
        // so replay is an upsert; live and replay share one state machine (HB-09).
        for (const entry of rec.entries) upsertEntry(doc, entry);
      } else {
        for (const op of rec.applied ?? []) applyOpPermissive(doc, op, rec.ts);
      }
      stats.records += 1;
    } catch {
      stats.badRecords += 1;
    }
  }
}

function bucketFor(doc: ProfileDoc, partition: Partition): { entries: ProfileEntry[] } {
  let bucket = doc.partitions[partition];
  if (!bucket) {
    bucket = { entries: [] };
    doc.partitions[partition] = bucket;
  }
  return bucket;
}

/** Journal v2 replay: `entry` is the entry's final state, so replay is an
 *  upsert by id (position preserved for updates, appended for new entries). */
function upsertEntry(doc: ProfileDoc, entry: ProfileEntry): void {
  const next = structuredClone(entry);
  for (const p of PARTITIONS) {
    const list = doc.partitions[p]?.entries;
    if (!list) continue;
    const at = list.findIndex((e) => e.id === next.id);
    if (at < 0) continue;
    if (p === next.partition) {
      list[at] = next;
    } else {
      list.splice(at, 1);
      bucketFor(doc, next.partition).entries.push(next);
    }
    return;
  }
  bucketFor(doc, next.partition).entries.push(next);
}

/** Full replay: snapshot basepoint + archive shards + live journal. */
export function replayJournal(guard: PathGuard, dataDir: string): ReplayResult {
  const snap = loadSnapshot(guard, dataDir);
  const doc = snap ? snap.doc : emptyProfile();
  const baselineTs = snap?.baselineTs ?? '';
  const stats = { records: snap?.recordsFolded ?? 0, truncatedTail: 0, badRecords: 0, isLive: false };
  for (const file of listArchiveFiles(guard, dataDir)) {
    try {
      // shard record counts are not reported (the snapshot already folded
      // them); only the live journal's torn tail is meaningful.
      replayText(doc, fs.readFileSync(path.join(dataDir, file), 'utf8'), baselineTs, { records: 0, truncatedTail: 0, badRecords: 0, isLive: false });
    } catch { /* unreadable shard: skip */ }
  }
  stats.isLive = true;
  replayText(doc, readText(guard, journalFilePath(dataDir), ''), baselineTs, stats);
  return { doc, truncatedTail: stats.truncatedTail, records: stats.records, badRecords: stats.badRecords };
}

/** Every plaintext journal text in chronological order: archive shards first,
 *  then the live journal — the RAW record timeline, for callers that need the
 *  history itself rather than the accumulated doc (the weekly report counts
 *  the week's ADD ops). A rotation must not hide history from them (H-01). */
export function readJournalTexts(guard: PathGuard, dataDir: string): string[] {
  const texts: string[] = [];
  for (const file of listArchiveFiles(guard, dataDir)) {
    try {
      texts.push(fs.readFileSync(path.join(dataDir, file), 'utf8'));
    } catch { /* unreadable shard: skip */ }
  }
  texts.push(readText(guard, journalFilePath(dataDir), ''));
  return texts;
}

export function loadProfile(guard: PathGuard, file: string): ProfileDoc {
  const doc = loadJson<ProfileDoc>(guard, file);
  if (!doc || !doc.partitions) return emptyProfile();
  // ensure all partitions exist
  for (const p of PARTITIONS) {
    if (!doc.partitions[p]) doc.partitions[p] = { entries: [] };
  }
  return doc;
}

function parseIso(v: string): number {
  const t = Date.parse(v);
  return Number.isFinite(t) ? t : 0;
}

/** ref format "<datafile>#<locator>": the referenced file must exist under data/. */
function refExists(guard: PathGuard, dataDir: string, ref: string): boolean {
  const base = ref.split('#')[0] ?? '';
  if (!base) return false;
  const target = path.join(dataDir, base);
  try {
    return fs.existsSync(guard.assert(target));
  } catch {
    return false;
  }
}

function capForKinds(kinds: EvidenceKind[]): number {
  if (kinds.length === 0) return 0.4;
  return Math.min(...kinds.map((k) => CONFIDENCE_CAP[k] ?? 0.4));
}

function findActive(doc: ProfileDoc, id: string): ProfileEntry | undefined {
  for (const p of PARTITIONS) {
    const hit = doc.partitions[p]!.entries.find((e) => e.id === id && e.validTo === null);
    if (hit) return hit;
  }
  return undefined;
}

/**
 * Apply validated ops to the doc (mutates). Returns applied/rejected.
 * Guards (§3.3): whitelist, evidence gate, per-run ops cap is enforced by the
 * caller, confidence caps by evidence kind, psy gating, INVALIDATE ownership:
 * volatile expiry is code-driven (LLM may not), stable invalidation needs a
 * contradicting observation attached.
 */
export function applyOpsToDoc(
  guard: PathGuard,
  dataDir: string,
  doc: ProfileDoc,
  ops: ProfileOp[],
  schema: ProfileSchema | undefined,
  policy: Policy,
  now: number,
): ApplyReport {
  const applied: ProfileOp[] = [];
  const rejected: { op: ProfileOp; reason: string }[] = [];
  // Journal v2 events: one FULL snapshot per touched entry (HB-09).
  const entries: ProfileEntry[] = [];
  const nowIso = new Date(now).toISOString();

  for (const op of ops) {
    if (op.op === 'NOOP') {
      applied.push(op);
      continue;
    }
    if (op.op === 'ADD') {
      if (op.partition === 'psy' && !policy.profile.psyEnabled) {
        rejected.push({ op, reason: 'psy partition is disabled' });
        continue;
      }
      let temporal: 'stable' | 'volatile' = 'stable';
      if (schema) {
        const check = checkAddAgainstSchema(schema, op.partition, op.topic, op.subTopic, op.temporal);
        if (!check.ok) {
          rejected.push({ op, reason: check.reason! });
          continue;
        }
        temporal = check.temporal;
      } else if (!(op.partition in doc.partitions)) {
        // H-17: no usable schema — the partition set is the only boundary left.
        rejected.push({ op, reason: `unknown partition: ${op.partition}` });
        continue;
      } else {
        temporal = op.temporal === 'volatile' ? 'volatile' : 'stable';
      }
      if (!op.evidence || op.evidence.length === 0) {
        rejected.push({ op, reason: 'ADD without evidence (no provenance, axiom 1)' });
        continue;
      }
      const badRef = op.evidence.find((e) => !refExists(guard, dataDir, e.ref));
      if (badRef) {
        rejected.push({ op, reason: `evidence ref does not resolve: ${badRef.ref}` });
        continue;
      }
      const cap = capForKinds(op.evidence.map((e) => e.kind));
      const active = doc.partitions[op.partition]!.entries.filter((e) => e.validTo === null);
      if (active.length >= policy.profile.partitionCap) {
        rejected.push({ op, reason: `partition ${op.partition} at cap (${policy.profile.partitionCap}); converge first` });
        continue;
      }
      dbSeq += 1;
      const entry: ProfileEntry = {
        id: `p${dbSeq.toString(36)}${randomUUID().slice(0, 4)}`,
        partition: op.partition,
        topic: op.topic,
        subTopic: op.subTopic,
        content: op.content.trim(),
        confidence: Math.min(op.confidence ?? cap, cap),
        temporal,
        validFrom: nowIso,
        validTo: null,
        supersededBy: null,
        evidence: op.evidence,
        createdAt: nowIso,
        updatedAt: nowIso,
        updateCount: 0,
      };
      op.assignedId = entry.id; // journal replay must reproduce this id
      doc.partitions[op.partition]!.entries.push(entry);
      entries.push(structuredClone(entry));
      applied.push(op);
      continue;
    }
    if (op.op === 'UPDATE') {
      const entry = findActive(doc, op.id);
      if (!entry) {
        rejected.push({ op, reason: `unknown or inactive entry: ${op.id}` });
        continue;
      }
      // HB-04 (2026-10-17): validate BEFORE mutating. The old order wrote
      // `content` first and then bailed out on the confidence rule, so an
      // UPDATE that was reported as REJECTED had already changed the text.
      let nextConfidence: number | null = null;
      if (op.changes.confidence !== undefined) {
        const cap = capForKinds(entry.evidence.map((e) => e.kind));
        // confidence upgrades need a second confirming observation (§3.3):
        // only allowed up to cap, and only when the entry already has 2+ evidence
        if (op.changes.confidence > entry.confidence && entry.evidence.length < 2) {
          rejected.push({ op, reason: 'confidence upgrade requires a second confirming observation' });
          continue;
        }
        nextConfidence = Math.min(op.changes.confidence, cap);
      }
      if (op.changes.content !== undefined) entry.content = op.changes.content.trim();
      if (nextConfidence !== null) entry.confidence = nextConfidence;
      entry.updatedAt = nowIso;
      entry.updateCount += 1;
      entries.push(structuredClone(entry));
      applied.push(op);
      continue;
    }
    if (op.op === 'INVALIDATE') {
      const entry = findActive(doc, op.id);
      if (!entry) {
        rejected.push({ op, reason: `unknown or inactive entry: ${op.id}` });
        continue;
      }
      if (entry.temporal === 'volatile') {
        rejected.push({ op, reason: 'volatile expiry is code-owned (time-driven), not LLM-nominated' });
        continue;
      }
      // stable: rebuttal-driven; requires a contradicting observation attached
      const hasNewObservation = (op.evidence ?? []).length > 0
        && (op.evidence ?? []).some((e) => parseIso(e.at) > parseIso(entry.evidence[entry.evidence.length - 1]?.at ?? ''));
      if (!hasNewObservation) {
        rejected.push({ op, reason: 'stable INVALIDATE requires a newer contradicting observation' });
        continue;
      }
      entry.validTo = nowIso;
      entry.supersededBy = null;
      entry.updatedAt = nowIso;
      entry.updateCount += 1;
      if (op.evidence) entry.evidence.push(...op.evidence);
      entries.push(structuredClone(entry));
      applied.push(op);
      continue;
    }
  }
  return { applied, rejected, entries };
}

let dbSeq = 0;

/** Deterministic aging (D9): volatile expiry + stable low-activity marking. */
export function runDeterministicAging(
  doc: ProfileDoc,
  policy: Policy,
  now: number,
): { volatileExpired: number; lowActivityMarked: number; entries: ProfileEntry[] } {
  const nowIso = new Date(now).toISOString();
  const entries: ProfileEntry[] = [];
  let volatileExpired = 0;
  let lowActivityMarked = 0;
  for (const p of PARTITIONS) {
    for (const e of doc.partitions[p]!.entries) {
      if (e.validTo !== null) continue;
      const lastEvidence = Math.max(...e.evidence.map((x) => parseIso(x.at)), parseIso(e.updatedAt));
      if (e.temporal === 'volatile') {
        if (now - lastEvidence > policy.profile.volatileDays * DAY_MS) {
          e.validTo = nowIso;
          e.updatedAt = nowIso;
          e.updateCount += 1;
          volatileExpired += 1;
          entries.push(structuredClone(e));
        }
      } else if (!e.lowActivity && now - lastEvidence > policy.profile.stableLowActivityDays * DAY_MS) {
        e.lowActivity = true;
        lowActivityMarked += 1;
        entries.push(structuredClone(e));
      }
    }
  }
  return { volatileExpired, lowActivityMarked, entries };
}

/** Persist the materialized view atomically + append the journal record.
 *  A record carrying `entries` (every touched entry's final state) is written
 *  as v2 so replay is an upsert; a record without them stays v1 and replays
 *  permissively, so old journals keep working unchanged. */
export function persistWithJournal(
  guard: PathGuard,
  dataDir: string,
  doc: ProfileDoc,
  record: Omit<JournalRecord, 'ts'>,
): void {
  saveJson(guard, profileFilePath(dataDir), doc);
  const v = record.entries === undefined ? undefined : JOURNAL_VERSION;
  const line = JSON.stringify({ ts: new Date().toISOString(), ...record, v });
  const journal = journalFilePath(dataDir);
  try {
    fs.appendFileSync(guard.assert(journal), line + '\n', 'utf8');
  } catch {
    fs.mkdirSync(dataDir, { recursive: true });
    fs.appendFileSync(guard.assert(journal), line + '\n', 'utf8');
  }
}

// ── journal replay (verify / rebuild, r2 §14) ───────────────────────────

function applyOpPermissive(doc: ProfileDoc, op: ProfileOp, ts: string): void {
  // Journal is trusted history: replay applies without revalidation.
  if (op.op === 'ADD') {
    dbSeq += 1;
    doc.partitions[op.partition]!.entries.push({
      id: op.assignedId ?? `r${dbSeq.toString(36)}${randomUUID().slice(0, 4)}`,
      partition: op.partition,
      topic: op.topic,
      subTopic: op.subTopic,
      content: op.content,
      confidence: op.confidence ?? 0.5,
      temporal: op.temporal ?? 'stable',
      validFrom: ts,
      validTo: null,
      supersededBy: null,
      evidence: op.evidence,
      createdAt: ts,
      updatedAt: ts,
      updateCount: 0,
    });
    return;
  }
  if (op.op === 'UPDATE') {
    const e = [...PARTITIONS].flatMap((p) => doc.partitions[p]!.entries).find((x) => x.id === op.id);
    if (e) {
      if (op.changes.content !== undefined) e.content = op.changes.content;
      if (op.changes.confidence !== undefined) e.confidence = op.changes.confidence;
      e.updatedAt = ts;
      e.updateCount += 1;
    }
    return;
  }
  if (op.op === 'INVALIDATE') {
    const e = [...PARTITIONS].flatMap((p) => doc.partitions[p]!.entries).find((x) => x.id === op.id);
    if (e) {
      e.validTo = ts;
      e.updatedAt = ts;
      e.updateCount += 1;
    }
  }
  // NOOP: nothing
}

export interface ReplayResult {
  doc: ProfileDoc;
  truncatedTail: number;
  records: number;
  /** Journal lines that neither parsed nor replayed (counted, never fatal). */
  badRecords?: number;
}

export interface VerifyReport {
  ok: boolean;
  firstDivergence?: { id: string; expected: string; actual: string };
  truncatedTail: number;
  records: number;
}

/** profile verify: replay vs disk, report first divergence, never fix. */
export function verifyProfile(guard: PathGuard, dataDir: string): VerifyReport {
  const replayed = replayJournal(guard, dataDir);
  const onDisk = loadProfile(guard, profileFilePath(dataDir));
  // Timestamps legitimately differ (journal record ts >= op ts); identity
  // fields are also normalized. Compare semantic content only.
  const strip = (doc: ProfileDoc): string =>
    JSON.stringify(doc.partitions, (k, v) => (['id', 'supersededBy', 'validFrom', 'createdAt', 'updatedAt', 'retiredAt'].includes(k) ? '<norm>' : v));
  const ok = strip(replayed.doc) === strip(onDisk);
  if (ok) return { ok: true, truncatedTail: replayed.truncatedTail, records: replayed.records };
  // first divergence: first entry id present in only one view
  const diskIds = new Set([...PARTITIONS].flatMap((p) => onDisk.partitions[p]!.entries.map((e) => e.content)));  const replayIds = new Set([...PARTITIONS].flatMap((p) => replayed.doc.partitions[p]!.entries.map((e) => e.content)));
  const onlyDisk = [...diskIds].find((c) => !replayIds.has(c));
  const onlyReplay = [...replayIds].find((c) => !diskIds.has(c));
  return {
    ok: false,
    firstDivergence: {
      id: onlyDisk ?? onlyReplay ?? '(content)',
      expected: onlyReplay ? 'absent in journal replay' : 'present in journal replay',
      actual: onlyDisk ? 'present on disk' : 'absent on disk',
    },
    truncatedTail: replayed.truncatedTail,
    records: replayed.records,
  };
}

export interface RebuildReport {
  ok: boolean;
  truncatedTail: number;
  records: number;
  wrote: boolean;
}

/** profile rebuild: journal is authoritative; atomic replace; torn tail reported. */
export function rebuildProfile(
  guard: PathGuard,
  dataDir: string,
  opts: { check?: boolean } = {},
): RebuildReport & { diffSummary?: string } {
  const replayed = replayJournal(guard, dataDir);
  const target = profileFilePath(dataDir);
  if (opts.check) {
    const onDisk = loadProfile(guard, target);
    const same = JSON.stringify(onDisk) === JSON.stringify(replayed.doc);
    return {
      ok: same,
      truncatedTail: replayed.truncatedTail,
      records: replayed.records,
      wrote: false,
      diffSummary: same ? 'no diff' : 'materialized view differs from journal replay',
    };
  }
  saveJson(guard, target, replayed.doc);
  if (replayed.truncatedTail > 0) {
    // explicit audit: never silently rebuild a view that lost its tail
    writeText(
      guard,
      path.join(dataDir, 'logs', 'rebuild-report.txt'),
      `rebuild truncated ${replayed.truncatedTail} torn line(s) at journal tail; ${replayed.records} records applied\n`,
    );
  }
  return { ok: true, truncatedTail: replayed.truncatedTail, records: replayed.records, wrote: true };
}

// ── wipe (HB-21, 2026-10-17) ───────────────────────────────────────────────
// `profile wipe` used to delete three files: the materialized view, the inbox
// and the live journal. The journal is the authority, and its history lives on
// in profile_snapshot.json plus the archive shards — so a rebuild after a wipe
// replayed the whole memory back, and a user who asked to forget got the
// profile regrown instead. Migration backups (HB-07) and crash leftovers carry
// copies of the same data.
//
// Wipe therefore removes every file the profile can be rebuilt from, and only
// that: settings, seeds, weekly reports and audit logs are not profile data and
// stay (burn is the tool for a full shred). Shredding remains burn's job — wipe
// is a delete, not a destroy.

const WIPE_FILES = ['profile.json', 'profile_inbox.jsonl', 'profile_journal.jsonl', SNAPSHOT_FILE];
const WIPE_PATTERNS: RegExp[] = [
  /^profile_journal\.archive-/,
  /\.bak-migrate-\d{14}$/,
  /\.incoming-\d{14}$/,
];

/** Delete every file the profile can be rebuilt from; returns what was removed
 *  (relative to dataDir, sorted per family). */
export function wipeProfile(guard: PathGuard, dataDir: string): string[] {
  const removed: string[] = [];
  for (const f of WIPE_FILES) {
    const abs = guard.assert(path.join(dataDir, f));
    if (fs.existsSync(abs)) {
      fs.rmSync(abs, { force: true });
      removed.push(f);
    }
  }
  for (const re of WIPE_PATTERNS) {
    let rels: string[] = [];
    try {
      rels = matchFilesRecursive(guard.assert(dataDir), re);
    } catch {
      rels = [];
    }
    for (const rel of rels) {
      try {
        fs.rmSync(guard.assert(path.join(dataDir, rel)), { force: true });
        removed.push(rel);
      } catch {
        /* already gone */
      }
    }
  }
  return removed;
}
